const id = $json.body.message_id;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof id !== 'string' || !uuidRe.test(id)) {
  throw new Error('message_id missing or not a valid UUID: ' + JSON.stringify(id));
}
return [{ json: { message_id: id } }];

const msg = $('Get message').item.json;
const campaign = $('Get campaign for action').item.json;
if (!campaign || !campaign.id) {
  throw new Error('No campaign linked to this message (messages.campaign_id is empty) — cannot apply the proposed action.');
}
const rawCustomerId = campaign.google_ads_customer_id;
if (!rawCustomerId) {
  throw new Error('This campaign has no google_ads_customer_id set.');
}
const customerId = String(rawCustomerId).replace(/[^0-9]/g, '');

// Same direct-access exception as build-campaign.json's Prepare context.
const DIRECT_ACCESS_CUSTOMER_IDS = ['3534195221'];
const mccCustomerId = $('Get Google Ads credentials').item.json.mcc_customer_id;
const loginCustomerId = DIRECT_ACCESS_CUSTOMER_IDS.includes(customerId) ? '' : mccCustomerId;

const action = msg.proposed_action;
if (!action || !action.action_type) {
  throw new Error('No proposed_action on this message.');
}

let urlSuffix, body;

if (action.action_type === 'update_daily_budget') {
  if (!campaign.google_ads_budget_resource) {
    throw new Error('This campaign has no google_ads_budget_resource on file (it was likely built before that field was added) — update it manually in Supabase or rebuild the campaign before this action type can be applied.');
  }
  if (typeof action.daily_budget_usd !== 'number') {
    throw new Error('proposed_action.daily_budget_usd is missing or not a number.');
  }
  urlSuffix = 'campaignBudgets:mutate';
  body = {
    operations: [{
      update: {
        resourceName: campaign.google_ads_budget_resource,
        amountMicros: String(Math.round(action.daily_budget_usd * 1000000)),
      },
      updateMask: 'amountMicros',
    }],
  };
} else if (action.action_type === 'pause_campaign' || action.action_type === 'resume_campaign') {
  if (!campaign.google_ads_campaign_resource) {
    throw new Error('This campaign has no google_ads_campaign_resource on file.');
  }
  urlSuffix = 'campaigns:mutate';
  body = {
    operations: [{
      update: {
        resourceName: campaign.google_ads_campaign_resource,
        status: action.action_type === 'pause_campaign' ? 'PAUSED' : 'ENABLED',
      },
      updateMask: 'status',
    }],
  };
} else {
  throw new Error('Unknown proposed_action.action_type: ' + action.action_type);
}

return [{ json: { customerId, loginCustomerId, urlSuffix, body } }];

